virtual void execute() {
  xBefore_ = unit_->x();
  yBefore_ = unit_->y();
  unit_->moveTo(x_, y_);
}

virtual void undo() {
  unit_->moveTo(xBefore_, yBefore_);
}

function makeMoveUnitCommand(unit, x, y) {
  var xBefore, yBefore;
  return {
    execute: function() {
      xBefore = unit.x(); yBefore = unit.y();
      unit.moveTo(x, y);
    },
    undo: function() { unit.moveTo(xBefore, yBefore); }
  };
}
